export interface ConnectorConfig {
  /** HubSpot private app access token. Env: HUBSPOT_ACCESS_TOKEN */
  hubspotAccessToken?: string;
  /** MindCloud Universal API token with Google Sheets scope. Env: MINDCLOUD_API_TOKEN */
  mindcloudApiToken: string;
  /** HubSpot API base URL. Default: https://api.hubapi.com */
  hubspotBaseUrl?: string;
  /** HubSpot engagement search endpoint URL (must support query params email and start_time). Required if hubspotEngagementId is not provided. */
  hubspotSearchUrl?: string;
  /** Optional fixed engagement ID to delete (for testing or when search is not needed). */
  hubspotEngagementId?: string;
  /** Google Sheets spreadsheet ID. */
  googleSheetsSpreadsheetId: string;
  /** Google Sheets worksheet/tab name. */
  googleSheetsWorksheet: string;
  /** Injected fetch implementation (for testing). */
  fetch?: typeof fetch;
}

export interface CalendlyWebhookPayload {
  invitee: {
    email: string;
  };
  start_time: string;
  cancellation_reason: string;
}

export interface HandleResult {
  hubspotEngagementDeleted?: string;
  googleSheetsRowAppended?: {
    spreadsheetId: string;
    range: string;
  };
}

async function fetchJson<T>(fetch: typeof fetch, url: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(url, init);
  if (!response.ok) {
    throw new Error(`${init.method ?? 'GET'} ${url} failed: ${response.status} ${response.statusText}`);
  }
  return response.json() as Promise<T>;
}

export async function handle(
  payload: CalendlyWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.invitee?.email) {
    throw new Error('Missing required field: invitee.email');
  }
  if (!payload.start_time) {
    throw new Error('Missing required field: start_time');
  }
  if (!payload.cancellation_reason) {
    throw new Error('Missing required field: cancellation_reason');
  }

  const fetch = config.fetch ?? globalThis.fetch;
  if (!fetch) {
    throw new Error('fetch is not available');
  }

  const email = payload.invitee.email;
  const startTime = payload.start_time;
  const cancellationReason = payload.cancellation_reason;

  let engagementId = config.hubspotEngagementId;
  let hubspotDeleted: string | undefined;

  if (config.hubspotAccessToken) {
    if (!engagementId) {
      if (!config.hubspotSearchUrl) {
        throw new Error('HubSpot engagement ID not provided and no search URL configured');
      }
      const searchUrl = new URL(config.hubspotSearchUrl);
      searchUrl.searchParams.set('email', email);
      searchUrl.searchParams.set('start_time', startTime);

      const searchResult = await fetchJson<{ results?: Array<{ id: string }> }>(fetch, searchUrl.toString(), {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${config.hubspotAccessToken}`,
          'Content-Type': 'application/json',
        },
      });

      if (!searchResult.results?.length) {
        throw new Error(`No HubSpot engagement found for email ${email} and start_time ${startTime}`);
      }
      engagementId = searchResult.results[0].id;
    }

    const hubspotBaseUrl = config.hubspotBaseUrl ?? 'https://api.hubapi.com';
    const deleteUrl = `${hubspotBaseUrl}/crm/v3/objects/engagements/${engagementId}`;

    await fetchJson(fetch, deleteUrl, {
      method: 'DELETE',
      headers: {
        'Authorization': `Bearer ${config.hubspotAccessToken}`,
      },
    });
    hubspotDeleted = engagementId;
  }

  const sheetsUrl = 'https://connect.mindcloud.co/v2/universal/apps/googleSheets/actions/append-rows/run';
  const sheetsBody = {
    arguments: {
      spreadsheetId: config.googleSheetsSpreadsheetId,
      worksheet: config.googleSheetsWorksheet,
      'values[]': [
        {
          col1: email,
          col2: startTime,
          col3: cancellationReason,
        },
      ],
    },
  };

  const sheetsResult = await fetchJson<{
    success: boolean;
    data?: Array<{ spreadsheetId: string; tableRange: string }>;
  }>(fetch, sheetsUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.mindcloudApiToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(sheetsBody),
  });

  if (!sheetsResult.success || !sheetsResult.data?.length) {
    throw new Error('Google Sheets append returned unexpected response');
  }

  return {
    hubspotEngagementDeleted: hubspotDeleted,
    googleSheetsRowAppended: {
      spreadsheetId: sheetsResult.data[0].spreadsheetId,
      range: sheetsResult.data[0].tableRange,
    },
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, CalendlyWebhookPayload, HandleResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      mindcloudApiToken: 'test-mindcloud-token',
      googleSheetsSpreadsheetId: '1aBcDeFgHiJkLmNoPqRsTuVwXyZ',
      googleSheetsWorksheet: 'Audit Log',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as CalendlyWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.googleSheetsRowAppended).toBeDefined();
    expect(result.googleSheetsRowAppended?.spreadsheetId).toBe('1aBcDeFgHiJkLmNoPqRsTuVwXyZ');
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    hubspotAccessToken: 'test-hubspot-token',
    hubspotSearchUrl: 'https://api.hubapi.com/crm/v3/objects/engagements/search',
    hubspotBaseUrl: 'https://api.hubapi.com',
    mindcloudApiToken: 'test-mindcloud-token',
    googleSheetsSpreadsheetId: '1aBcDeFgHiJkLmNoPqRsTuVwXyZ',
    googleSheetsWorksheet: 'Audit Log',
  };

  const validPayload: CalendlyWebhookPayload = {
    invitee: { email: 'user@example.com' },
    start_time: '2025-06-15T14:30:00Z',
    cancellation_reason: 'Schedule conflict',
  };

  it('deletes HubSpot engagement and appends Google Sheets row on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/engagements/search')) {
        return jsonResponse({ results: [{ id: 'eng-123' }] });
      }
      if (req.method === 'DELETE' && req.url.includes('/engagements/eng-123')) {
        return jsonResponse({}, 204);
      }
      if (req.method === 'POST' && req.url.includes('/append-rows/run')) {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validPayload, { ...baseConfig, fetch });
    expect(result.hubspotEngagementDeleted).toBe('eng-123');
    expect(result.googleSheetsRowAppended).toBeDefined();
    expect(calls).toHaveLength(3);
    expect(calls[0].method).toBe('GET');
    expect(calls[1].method).toBe('DELETE');
    expect(calls[2].method).toBe('POST');
    expect(calls[2].json).toEqual({
      arguments: {
        spreadsheetId: '1aBcDeFgHiJkLmNoPqRsTuVwXyZ',
        worksheet: 'Audit Log',
        'values[]': [{ col1: 'user@example.com', col2: '2025-06-15T14:30:00Z', col3: 'Schedule conflict' }],
      },
    });
  });

  it('uses provided hubspotEngagementId and skips search', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'DELETE' && req.url.includes('/engagements/eng-456')) {
        return jsonResponse({}, 204);
      }
      if (req.method === 'POST' && req.url.includes('/append-rows/run')) {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(validPayload, { ...baseConfig, hubspotEngagementId: 'eng-456', fetch });
    expect(result.hubspotEngagementDeleted).toBe('eng-456');
    expect(calls).toHaveLength(2);
    expect(calls[0].method).toBe('DELETE');
    expect(calls[1].method).toBe('POST');
  });

  it('skips HubSpot deletion when hubspotAccessToken is omitted', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'POST' && req.url.includes('/append-rows/run')) {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const configWithoutHubspot: ConnectorConfig = {
      mindcloudApiToken: 'test-mindcloud-token',
      googleSheetsSpreadsheetId: '1aBcDeFgHiJkLmNoPqRsTuVwXyZ',
      googleSheetsWorksheet: 'Audit Log',
      fetch,
    };

    const result = await handle(validPayload, configWithoutHubspot);
    expect(result.hubspotEngagementDeleted).toBeUndefined();
    expect(result.googleSheetsRowAppended).toBeDefined();
    expect(calls).toHaveLength(1);
    expect(calls[0].method).toBe('POST');
  });

  it('throws on missing invitee.email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = { ...validPayload, invitee: {} } as unknown as CalendlyWebhookPayload;
    await expect(handle(badPayload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: invitee.email');
  });

  it('throws on missing start_time', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = { ...validPayload, start_time: '' } as unknown as CalendlyWebhookPayload;
    await expect(handle(badPayload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: start_time');
  });

  it('throws on missing cancellation_reason', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const badPayload = { ...validPayload, cancellation_reason: '' } as unknown as CalendlyWebhookPayload;
    await expect(handle(badPayload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: cancellation_reason');
  });

  it('throws on HubSpot search 404', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/engagements/search')) {
        return jsonResponse({ error: 'not found' }, 404);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('GET https://api.hubapi.com/crm/v3/objects/engagements/search failed: 404 Not Found');
  });

  it('throws when HubSpot search returns no results', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/engagements/search')) {
        return jsonResponse({ results: [] });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('No HubSpot engagement found for email user@example.com and start_time 2025-06-15T14:30:00Z');
  });

  it('throws on HubSpot delete 404', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/engagements/search')) {
        return jsonResponse({ results: [{ id: 'eng-123' }] });
      }
      if (req.method === 'DELETE' && req.url.includes('/engagements/eng-123')) {
        return jsonResponse({ error: 'not found' }, 404);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('DELETE https://api.hubapi.com/crm/v3/objects/engagements/eng-123 failed: 404 Not Found');
  });

  it('throws on Google Sheets append 401', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/engagements/search')) {
        return jsonResponse({ results: [{ id: 'eng-123' }] });
      }
      if (req.method === 'DELETE' && req.url.includes('/engagements/eng-123')) {
        return jsonResponse({}, 204);
      }
      if (req.method === 'POST' && req.url.includes('/append-rows/run')) {
        return jsonResponse({ error: 'unauthorized' }, 401);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('POST https://connect.mindcloud.co/v2/universal/apps/googleSheets/actions/append-rows/run failed: 401 Unauthorized');
  });

  it('throws when Google Sheets returns success false', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/engagements/search')) {
        return jsonResponse({ results: [{ id: 'eng-123' }] });
      }
      if (req.method === 'DELETE' && req.url.includes('/engagements/eng-123')) {
        return jsonResponse({}, 204);
      }
      if (req.method === 'POST' && req.url.includes('/append-rows/run')) {
        return jsonResponse({ success: false, data: [] });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    await expect(handle(validPayload, { ...baseConfig, fetch })).rejects.toThrow('Google Sheets append returned unexpected response');
  });
});

